args.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?released ?year WHERE {
  VALUES ?film { dbr:Edurinti_Mogudu_Pakkinti_Pellam dbr:Family_of_Strangers }
  OPTIONAL { ?film dbp:released ?released. }
  BIND(
    IF(datatype(?released)=xsd:date, YEAR(?released), xsd:integer(str(?released))) AS ?year
  )
}
ORDER BY ?year
LIMIT 2

